                title: '1. Эторфин (M99) и Тиафентанил (A3080)',
                content: `
### Сверхактивные опиоидные агонисты
Химическая иммобилизация слонов основана на применении полусинтетических опиоидов высокой мощности.

**Эторфина гидрохлорид (M99):**
* **Фармакологический профиль:** Полусинтетический опиоид, производное тебаина. Анальгетическая активность в 10 000 – 80 000 раз превышает морфин. Высокоселективный агонист μ-, κ- и δ-опиоидных рецепторов ЦНС.
* **Дозирование для диких слонов (Free-ranging):** 2.0–3.0 мг/т массы тела (8–12 мг на быка 4–5 т) из-за высокого стресса и необходимости быстрой индукции.
* **Дозирование для слонов в неволе (Captive):** 0.5–1.0 мг/т в сочетании с транквилизаторами при контролируемой среде.
* **Фармакокинетика:** Полная индукция через 7–15 минут после внутримышечного введения.

**Тиафентанила оксалат (A3080):**
* **Фармакологический профиль:** Синтетический опиоид фентанилового ряда, активность в 2–3 раза выше эторфина при более быстром начале действия.
* **Дозирование:** 1.5–2.5 мг/т.
* **Преимущества:** Время индукции 3–6 минут (критично при отлове в холмистой местности). Менее выраженное угнетение дыхания на пике индукции.
                `
