                content: `
### Биореактор слепой кишки
Слоны представляют собой вершину эволюции моногастричных нежвачных мегатравоядных, выстроивших адаптивную стратегию «быстрого транзита и высокого объёма потребления» (high throughput strategy).

* **Относительная длина ЖКТ:** Общая длина кишечника слона превышает длину тела всего в 2.5–3.5 раза (около 30–37 метров), в то время как у лошади ЖКТ превышает длину тела в 12 раз.
* **Эффективность усвоения клетчатки:** Из-за быстрой эвакуации химуса (время транзита 24–33 часа) переваривание сухой массы целлюлозы сравнительно низкое: 40–50% у азиатских слонов и 22–44% у африканских слонов.
* **Биореактор слепой кишки (Caecum):** Главным локусом целлюлозолитического гидролиза выступает гигантская слепая кишка объёмной вместимостью 150–200 литров (масса органа с содержимым составляет до 12% от массы тела животного). В анаэробных условиях слепой кишки при рН 6.2–6.8 многокомпонентный консорциум анаэробных бактерий (Fibrobacter, Ruminococcus), инфузорий и анаэробных грибов осуществляет ферментацию растительных полисахаридов.
                `
