                content: `
### Positive Reinforcement Training (PRT)
Оперантное обучение (Positive Reinforcement Training, PRT) в рамках PC позволяет выполнять любые инвазивные ветеринарные манипуляции без седации и фиксации.

**Ключевые инструменты PRT:**
* Маркер (Свисток / Кликер): Акустический сигнал, подаваемый в точную секунду совершения правильного действия, обозначающий подкрепление (bridge signal).
* Таргет (Target Stick): Шест с мягким шариком на конце, к которому слон прикасается определённой частью тела (кончиком хобота, стопой, ухом).
* Первичное подкрепление: Высококалорийное лакомство (кусочки яблок, моркови, бананов).

**Отработанные ветеринарные поведения (Veterinary Behaviors):**
1. Подача стопы (Foot presentation): Помещение ноги на подставку в окне стены для ортопедической расчистки и обработки раны.
2. Подача уха (Ear presentation): Фиксация ушной раковины для забора крови из краевой вены (v. auricularis posterior) или IV-инфузии.
3. Промывание хобота (Trunk Wash): Введение 60 мл стерильного физраствора в ноздрю хобота с последующим выдуванием жидкости в стерильный пакет для ПЦР-детекции туберкулёза или EEHV.
4. Принятие ректального катетера: Спокойное удержание положения при введении ректального зонда для подачи Фамцикловира при EEHV или клизмы при коликах.

[CLINICAL GUIDANCE]
**Преимущества PRT:**
* Отсутствие стресса и риска ПТСР
* Возможность выполнения сложных ветеринарных процедур без седации
* Повышение безопасности персонала
* Улучшение благополучия и автономии слона
                `
