                content: `### Ургентная терапевтическая схема при EEHV-HD
При обнаружении виремии (≥ 10³ копий/мкл) или падении тромбоцитов лечение начинают мгновенно.

#### 1. Специфические антивирусные препараты:
* **Фамцикловир (Золотой стандарт):**
  * *Перорально (PO):* **15 мг/кг каждые 8 часов (TID)**. Из-за горького вкуса смешивают с патокой или банановым пюре. Биодоступность — **18–22%** (расщепляется микробиомом слепой кишки).
  * *Ректально (per rectum):* **10 мг/кг каждые 8 часов (TID)**. Приоритетен при анорексии. Биодоступность достигает **35–40%**.
* **Ацикловир (Альтернатива):** **12 мг/кг IV медленно BID** или **45 мг/кг PO TID**.
* **Ганцикловир (Резерв):** **5 мг/кг IV BID** при тяжелых рефрактерных формах.

#### 2. Инфузионная коррекция гемодинамики и гемотрансфузия:
* **Кристаллоидная терапия:** Запрещен изотонический 0.9% NaCl в чистом виде! Из-за исходно низкой осмолярности сыворотки слонов 0.9% NaCl работает для них как гипертонический раствор, усиливая экссудацию и отеки. Применяют подогретые **низкотонические комплексные растворы со скоростью 4 мл/кг/час** (при шоке — до 90 мл/кг/час).
* **Гемотрансфузия плазмы:** При падении тромбоцитов **< 30 × 10⁹/л** проводят трансфузию свежей плазмы (0.5–2 мл/кг) от qPCR-отрицательной матери или взрослого сородича с кросс-матчинг контролем.

[CLINICAL GUIDANCE]
**Превентивная и симптоматическая терапия:**
Всем слонятам группы риска показано ежедневное профилактическое введение **Витамина C (аскорбиновой кислоты) в дозе 6 мг/кг/сутки PO** для укрепления эндотелия и интерфероногенеза. Для профилактики бактериальной септицемии при ДВС назначают **Цефтриаксон (20 мг/кг IV SID)**, а для гастропротекции от стрессовых язв — **Омепразол (0.7–1.4 мг/кг PO SID)**.`,
