                title: '1. Кооперативная парадигма: Тест с совместным вытягиванием каната (Loose-String Task)',
                content: `### Экспериментальная биомеханика совместного действия (Plotnik et al., 2011)
Исследования Джошуа Плотника (*Joshua Plotnik*) и Франса де Вааля (*Frans de Waal*) с азиатскими слонами (*Elephas maximus*) доказали наличие у хоботных понимания роли партнера и физической механики совместной работы.

* **Конструкция установки:** Выдвижная тяжелая платформа с приманкой расположена за пределами вольера. Через нее пропущен свободный канат. Если один слон потянет за конец каната раньше второго, канат вытянется через шкив, а приманка останется недосягаемой.
* **Результаты с задержкой партнера:**
  1. *Понимание роли партнера:* Когда одного слона выпускали на площадку раньше другого, он **останавливался перед канатом и ждал партнера** (задержка до 45 секунд), не прикасаясь к своей петле до подхода сородича.
  2. *Понимание механики инструмента:* Если конец каната партнера был заблокирован или спрятан, слон полностью отказывался тянуть свой конец, осознавая бесполезность одиночных усилий.

    Одиночный запуск слона ──► Замирание у каната (ожидание до 45 сек)
                                         │
                                         ▼
    Подход партнера ──► Синхронный захват 2 концов ──► Выдвижение платформы`
