                content: `### Ментальная репрезентация и ментальный поиск решения (Foerder et al., 2011)
Долгое время считалось, что слоны уступают приматам в тестах с подтягиванием еды за палки. Однако Престон Фёрдер (*Preston Foerder*) доказал, что отсутствие результатов объяснялось анатомией: хобот — орган обоняния и осязания; удерживание в нем палки блокирует ноздри.

#### Эксперимент с молодым самцом Кандулой (Kandula, 7 лет):
1. **Постановка задачи:** Свежие бананы и побеги бамбука были подвешены на высоте **3.0 метра** под куполом вольера (недосягаемо для прямого дотягивания хоботом).
2. **Наличие опорного предмета:** В стороне от точки подвеса находился тяжелый пластиковый куб-подставка (*step tool*).
3. **Фаза ментального планирования:** После безуспешных прямых попыток Кандула отошел, замер и фиксировал взгляд на приманке и кубе без хаотических проб и ошибок.
4. **Спонтанное решение («Аха-момент»):** Слон подошел к кубу, хоботом и ногами подкатил его **точно под приманку**, встал на него передними ногами и легко достал бананы.
5. **Генерализация навыка:** В последующих тестах Кандула спонтанно задействовал в качестве опорных подставок альтернативные предметы — тракторные шины, деревянные бруски и спрессованные шары.

\`\`\`
 Подвешенная приманка (3.0 м) ──► Пауза и ментальное планирование
                                                │
                                                ▼
 Пространственная транспортировка куба ──► Подъем на Step Tool ──► Захват приманки
\`\`\``
